 private static void check(boolean value,String code)throws IOException{if(!value)throw new IOException(code);}
 private static void safe(File path,boolean directory)throws IOException{check(!Files.isSymbolicLink(path.toPath())&&path.getAbsoluteFile().equals(path.getCanonicalFile()),"AUDIO_PAYLOAD_PATH");if(path.exists())check(directory?path.isDirectory():path.isFile(),"AUDIO_PAYLOAD_PATH");}
