 private static void directory(File dir)throws IOException{safe(dir,true);if(!dir.exists()){check(dir.mkdir(),"AUDIO_PAYLOAD_DIRECTORY");sync(dir.getParentFile());}}
 private void current()throws IOException{check(!closed,"AUDIO_PAYLOAD_CLOSED");guard.check();}
 private void cleanupPartial()throws IOException{File[] children=accountDir.listFiles();check(children!=null&&children.length<=1024,"AUDIO_PAYLOAD_SCAN");for(File item:children){current();if(item.getName().matches("prepare-[a-f0-9]{32}\\.partial")){safe(item,false);check(item.length()<=AudioUploadWire.MAX,"AUDIO_PAYLOAD_SCAN");Files.delete(item.toPath());}else if(item.getName().matches("[a-f0-9]{64}")){safe(item,true);File[] values=item.listFiles();check(values!=null,"AUDIO_PAYLOAD_PATH");if(values.length==0)Files.delete(item.toPath());}}sync(accountDir);}
 /** Size-only accounting across accounts. No other account's contents read. */
 private long[] scan()throws IOException{current();safe(root,true);safe(accountDir,true);File[] accounts=root.listFiles();check(accounts!=null&&accounts.length<=97,"AUDIO_PAYLOAD_SCAN");long bytes=0,count=0;for(File owner:accounts){if(owner.getName().equals(".producer.lock")){safe(owner,false);check(owner.length()==0,"AUDIO_PAYLOAD_PATH");continue;}check(owner.getName().matches("[a-f0-9]{64}"),"AUDIO_PAYLOAD_PATH");safe(owner,true);File[] snapshots=owner.listFiles();check(snapshots!=null&&snapshots.length<=1024,"AUDIO_PAYLOAD_SCAN");for(File item:snapshots){check(++count<=entries,"AUDIO_PAYLOAD_CAPACITY");if(item.getName().matches("prepare-[a-f0-9]{32}\\.partial")){safe(item,false);check(item.length()<=AudioUploadWire.MAX,"AUDIO_PAYLOAD_SCAN");bytes=Math.addExact(bytes,item.length());continue;}check(item.getName().matches("[a-f0-9]{64}"),"AUDIO_PAYLOAD_PATH");safe(item,true);File[] content=item.listFiles();check(content!=null&&content.length<=1,"AUDIO_PAYLOAD_PATH");for(File f:content){check(f.getName().equals("payload.bin"),"AUDIO_PAYLOAD_PATH");safe(f,false);check(f.length()>0&&f.length()<=AudioUploadWire.MAX,"AUDIO_PAYLOAD_SCAN");bytes=Math.addExact(bytes,f.length());}}}check(bytes<=limit,"AUDIO_PAYLOAD_CAPACITY");return new long[]{bytes,count};}
 private static MessageDigest digest(){try{return MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
 private static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 private String hash(File file)throws IOException{MessageDigest hash=digest();safe(file,false);try(InputStream in=Files.newInputStream(file.toPath(),StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS)){byte[] bytes=new byte[65536];int count;while((count=in.read(bytes))!=-1){current();hash.update(bytes,0,count);}}return hex(hash.digest());}
 /** A cache hint never replaces complete source validation or byte hashing. */
