 private final class Output extends OutputStream {
  final FileChannel disk;final MessageDigest digest=digest();final long expected;long written;
  Output(FileChannel disk,long expected){this.disk=disk;this.expected=expected;}
  public void write(int b)throws IOException{write(new byte[]{(byte)b});}
  public void write(byte[] bytes,int at,int count)throws IOException{current();check(count>=0&&written+count<=expected&&(disk==null||accountDir.getUsableSpace()>67108864),"AUDIO_PAYLOAD_CAPACITY");if(disk!=null){java.nio.ByteBuffer buffer=java.nio.ByteBuffer.wrap(bytes,at,count);while(buffer.hasRemaining())check(disk.write(buffer)>0,"AUDIO_PAYLOAD_WRITE_FAILED");}digest.update(bytes,at,count);written+=count;}
 }
