  current();check(text!=null,"AUDIO_SOURCE_TEXT_NOT_STORED");session=WireJson.map(WireJson.copy(session));archive=WireJson.map(WireJson.copy(archive));final Map<String,Object> provenSession=session;Map<String,Object> c=WireJson.map(archive.get("context"));AudioUploadWire.keys(c,"account","peer","generation","clock_epoch");AudioUploadWire.keys(archive,"context","stream","first_sequence","count","phase","error");
